import {
    DragDropMajor,
    EditMinor,
    DuplicateMinor,
    DeleteMinor,
    ArrowDownMinor,
    ArrowUpMinor,
    backIcon
} from "@/assets/icons";
import { getIdParentAndIndex } from "@/utils/helpers";

export default {
    inject: ["eventBus"],
    computed: {
        locked() {
            return this.$store.getters["builder/editorConfigs"]?.locked;
        },
        conditionLiquid() {
            // If block contains a group, skip outer block condition and let the group handle its own.
            // Generating separate outer block condition wraps the group in {% if condition %}
            // which can block the group's own condition from being evaluated at all.
            if (this.data?.group) return {};
            return this.condition
                ? {
                      start: `{% assign condition = true %} ${this.condition} {% if condition %}`,
                      end: "{% endif %}"
                  }
                : {};
        },
        icons() {
            return {
                DragDropMajor,
                EditMinor,
                DuplicateMinor,
                DeleteMinor,
                ArrowDownMinor,
                ArrowUpMinor,
                backIcon
            };
        },
        block() {
            // Computed này bị buộc phải sync group.title/section vào data (nhiều nơi
            // đọc từ data), nhưng CHỈ được ghi khi giá trị thực sự đổi. Trước đây nó
            // gán object MỚI vào data.section ở mọi lần evaluate, trong khi deps gồm
            // cả mảng sections (findIndex) -> mỗi lần insert/xoá section là mọi block
            // trên page đồng loạt ghi lại data.section, trigger lại toàn bộ effect
            // đang track nó -> "Maximum recursive updates exceeded".
            if (this.data.group && this.data.group.title !== this.data.title) {
                this.data.group.title = this.data.title;
            }
            const sectionTitle =
                this.currentSection?.title ?? this.$t('section') + ' ' + (this.currentSectionIndex + 1);
            if (
                !this.data.section ||
                this.data.section.id !== this.section_id ||
                this.data.section.title !== sectionTitle
            ) {
                this.data.section = {
                    id: this.section_id,
                    title: sectionTitle
                };
            }
            return this.data;
        },
        currentSection(){
            return this.$store.getters['page/section'](this.section_id);
        },
        currentSectionIndex() {
            return this.sections.findIndex(item => item.id === this.section_id) || 0;
        },
        editing() {
            return this.editingElement;
        },
        editingData() {
            return this.editing && this.editing.data ? this.editing.data : {};
        },

        currentDrag() {
            return this.dropTo !== this && this.dragCurrent === this;
        },
        isFirst() {
            return this.index == 0;
        },
        isLast() {
            return (
                this.$parent &&
                this.$parent.$parent &&
                this.$parent.$parent.blocks &&
                this.index == this.$parent.$parent.blocks.length - 1
            );
        },
        type() {
            return this.data.row ? "row" : this.data.group ? "group" : "block";
        },
        canDrop() {
            return this.$helpers.canDrop(this.dragCurrent, this) && this.control;
        },
        appsLength() {
            return this.ecosystem_apps.length;
        },

        refreshId() {
            return this.block.group ? this.block.group.refresh : this.block.refresh;
        },

        screen() {
            return this.$store.getters["builder/screen"];
        },
        sections() {
            return this.$store.getters["page/sections"];
        },
        ecosystem_apps() {
            return this.$store.getters["page/ecosystem_apps"];
        },
        progress() {
            return this.$store.getters["global/progress"];
        }
    },
    methods: {
        createStyle() {
            if (this.$refs?.blockElement?.$el) {
                this.$helpers.addStyle2Component(this.$refs?.blockElement?.$el, this.data);
            }
        },
        processMenu(e) {
            const method = this.ctx[e] || this[e];
            if (typeof method === "function") {
                method(clipboard);
            }
        },

        currentScreen() {
            return this.$store.getters["builder/currentScreen"];
        },
        editOrDrag(e) {
            if (this.$refs.blockElement?.$el) {
                this.$refs.blockElement?.$el.dispatchEvent(
                    new CustomEvent("setactive", { detail: true })
                );
            }
        },
        overBlock(event: any) {
            if (!this.isFullScreen) {
                this.over = true;
                // this.parentsOut();
                clearTimeout(this.timmer);
            }
        },

        placehover(pos) {
            if (this.canDrop && this.isDragging) {
                if (this.section_id) {
                    this.$store.commit("builder/sectionDrag", this.section_id);
                }
                this.timmer = setTimeout(() => {
                    this.$store.commit("builder/setDropTo", this.data.id);
                    this.$store.commit("builder/setDropPos", pos);
                    this.placeholder = pos;
                }, 60);
            }
        },

        dragBlock(e) {
            // if (this.sidebarTabActive?.id === 'dragging_element_sidebar') {
            //     return;
            // }

            if (
                !this.isFullScreen &&
                (this.type == "block" || (this.deep == 4 && this.type == "row")) &&
                this.control &&
                !this.inGroup &&
                !this.isGrid
            ) {
                this.startDrag(e);
            }
        },

        activeBlock() {
            if (this.isFullScreen) {
                return;
            }

            if (this.type != "block") {
                // Click rơi vào vùng "chết" của Block bọc row lồng / group element
                // (tabs, slider, accordion, product box, ...) - không phần tử con
                // nào bắt được click cụ thể hơn. Vì root dùng @click.stop nên nếu
                // không active gì ở đây, click bị nuốt hoàn toàn và Column/Row cha
                // cũng không bao giờ nhận được để tự chọn chính nó. Chọn thẳng
                // instance thực sự, giống cách activeGroup() (mousedown) đang làm.
                if (this.$refs?.blockElement) {
                    this.$store.commit("builder/setDragging", { timmer: new Date().getTime() });
                    this.$store.commit("builder/setActiveElement", this);
                    this.$store.commit("builder/setEditingElement", this.$refs.blockElement);
                    this.$store.commit("builder/hideContextMenu");
                    this.eventBus.emit("groupSettingsClose");
                }
                return;
            }

            // For unbind select when click outside builder
            this.$store.commit("builder/setDragging", { timmer: new Date().getTime() });
            this.$store.commit("builder/setActiveElement", this);
            this.$store.commit("builder/hideContextMenu");
            this.eventBus.emit("groupSettingsClose");
            this.editBlock();
            // setTimeout(()=>{
            //     if( this.editingData.tab_active === 'presets')
            //         this.editingData.tab_active = 'content';
            // },100)
        },

        editBlock() {
            if (this.$refs?.blockElement?.settings || this.$refs?.blockElement?.style) {
                this.$store.commit("builder/setEditingElement", this.$refs.blockElement);
            }
        },

        editElement() {
            if (this.$refs?.blockElement?.active_child_elenent) {
                this.$refs.blockElement.active_child_elenent = null;
            }

            this.editBlock();
        },
        edit() {
            this.editBlock();
        },
        openPresetLibrary() {
            // this.$store.commit('builder/setEditingElement', this.$refs.blockElement);

            if (
                (this.$refs?.blockElement?.settings || this.$refs?.blockElement?.style) && this.hidden !== true
            ) {
                this.$store.commit("builder/setEditingElement", this.$refs.blockElement);
                this.$store.commit("builder/setActiveElement", this);
                if (this.$refs.blockElement.$options?.presets) {
                    this.editingData.tab_active = "presets";
                }
            }
        },
        paste(clipboard) {
            if (!clipboard) {
                return;
            }
            let data = this.$helpers.copy(clipboard.data),
                sect,
                col;
            if (data?.group) {
                data.group.id = this.$helpers.randid();
                data.group.settings.items.map((blocks) => {
                    blocks.blocks.map((block) => {
                        block.id = this.$helpers.randid();
                    });
                });
            }
            switch (clipboard.is) {
                case "section":
                    sect = this.parent("section");
                    sect.stack.splice(sect.index + 1, 0, data);
                    this.$store.dispatch('history/addStack', {
                        type: 'section',
                        index: sect.index + 1,
                        data:  data,
                        section_id: sect.data.id,
                        action: 'add'
                    });
                    this.scroll(sect.$refs?.wrapper?.offsetHeight ?? 0);
                    break;
                case "column":
                    // col = this.parent("section");
                    // if (col.stack.length >= 10) {
                    //     this.notice(
                    //         "Can not insert more than 10 columns in a " + col.$parent.is,
                    //         "error"
                    //     );
                    // } else {
                    //     col.stack.splice(col.index + 1, 0, data);
                    //     col.$parent.refreshCols();
                    // }
                    break;
                case "block":
                case "blockFlex":
                    if(this.inGrid) return;
                    data.id = this.$helpers.randid(); // Keep current data
                    this.stack.splice(this.index + 1, 0, data);
                    this.$store.dispatch('history/addStack', {
                        type: 'block',
                        index: this.index + 1,
                        data:  data,
                        section_id: this.section_id,
                        parent_id: this.parentColumn.data.id,
                        action: 'duplicated',
                    });
                    this.scroll((this.$refs?.wrapper?.offsetHeight ?? 0) / 2);
                    break;
            }
        },

        insertCol() {
            if (this.columns.length >= 10) {
                this.notice("Can not insert more than 10 columns in a row", "error");
            } else {
                this.columns.push({
                    width: Math.round(100 / (this.columns.length + 1)),
                    blocks: []
                });
                this.refreshCols();
            }
        },
        dropOut() {
            if (this.data.id == this.editingElement?.data?.id) {
                setTimeout(() => {
                    this.$store.dispatch("builder/setEditingElement", null);
                }, 50);
            }

            let currentID = this.data.id;
            let realIndex = this.stack.findIndex((item) => {
                return item.id === currentID;
            });
            if (isNaN(realIndex)) {
                realIndex = this.index;
            }
            const componentName = this?.data?.name || this?.data?.element;
            this.$store.commit("page/removeJavascript", {
                id: this.data.id,
                name: componentName
            });

            // Lấy item đã xóa
            const removedItem = this.stack && this.stack.splice(realIndex, 1)[0];
            // // THÊM: Phát sự kiện cập nhật layout
            const grid = this.findGridParent();
            if (grid) {
                this.eventBus.emit("remove-item", this.data.id);
                grid.differenceMouseItem = null;
            }

            return removedItem;
        },

        dropIn(target, pos) {
            if (target._column === this._column && target.index < pos && target.index > 0) {
                pos--;
            }

            let currentID = this.data.id;
            let realIndex = this.stack.findIndex((item) => {
                return item.id === currentID;
            });
            if (isNaN(realIndex)) {
                realIndex = this.index;
            }
            const thisFlex = this?.$parent?.$parent?.$parent;
            const targetFlex = target?.$parent?.$parent?.$parent;
            if (target.index < realIndex && ((target._column === this._column && !this.isFlexContainer && this.dragPosition !== "bottom") || (thisFlex && targetFlex && thisFlex.data.id === targetFlex.data.id))) {
                realIndex -= 1;
            }
            if (this.dragPosition === "bottom" && target._column !== this._column) {
                realIndex += 1;
            }
            if (this.section_id && this.sections?.length) {
                const { parent_id, index } = getIdParentAndIndex(target);
                if(!target.data.id) {
                    target.data.id = this.$helpers.randid();
                    target.data.IDInit = true;
                }
                this.$store.commit('builder/setStatusDuplicate', true);
                let payload = {
                    type: 'block',
                    data: target.data,
                    section_id: this.section_id,
                    action: "moved",
                    parent_id: parent_id,
                    index: index
                }
                this.$store.dispatch('history/addStack', payload);
                if(this.timmerMove) clearTimeout(this.timmerMove);
                this.timmerMove = setTimeout(() => {
                    this.$store.commit('builder/setStatusDuplicate', false);
                }, 500);
            }
            if(this.dragPosition == 'bottom') realIndex += 1;
            this.stack?.splice(realIndex + pos, 0, target.dropOut());

            // this.$store.dispatch('history/addStack', {
            //     type: target.name,
            //     name: '',
            //     action: target.editOnMounted ? 'Droped' : 'Moved'
            // });
        }
    },
    watch: {
        refreshId(val) {
            if (this.isMounted) {
                this.refreshKey = val;
            }
        },
        appsLength(value) {
            this.ecosystem_apps.forEach((elm: object) => {
                const com_name = componentName(elm.slug) + "Element";
                if (!this.$options?.components[com_name]) {
                    this.$options.components[com_name] = loadComponent(elm.data_url, [], { isEcosystemApp: true });
                }
            });
        }
    }
};
